import{_ as t,o as n,c as r,ag as a}from"./chunks/framework.W-j76G-U.js";const p=JSON.parse('{"title":"Lab 2 : automatiser une tâche récurrente","description":"","frontmatter":{},"headers":[],"relativePath":"handout-03-lab-2-tache-recurrente.md","filePath":"handout-03-lab-2-tache-recurrente.md","handout":{"fichier":"handout-03-lab-2-tache-recurrente.md","markdown":"# Handout — Lab 2 : automatiser une tâche récurrente\\n\\n**Bootcamp AI-Driven Development · Module 0 · Zenika · support d\'exercice**\\n\\nLab optionnel (~25 min) : transformer une tâche faite « à la main » chaque semaine en un Project ou une Skill réutilisable en 30 secondes.\\n\\n## Étapes\\n\\n1. **Choisir une tâche récurrente** : CR de réunion, relance client, brief offre, réponse candidat…\\n2. **Créer un Project / une Skill** dédié, avec un nom clair.\\n3. **Rédiger les instructions** : destinataire, ton, format de sortie, quoi éviter.\\n4. **Ajouter 2-3 exemples** en pièces jointes, ce qui fait passer de « correct » à « on dirait vous ».\\n5. **Tester sur un cas réel** et affiner selon ce qui manque ou dérape.\\n\\n> **Règle d\'or** : pas de données client confidentielles sans validation DSI, données anonymisées ou cas internes.\\n\\n## Project ou Skill ?\\n\\n|            | Project                                          | Skill                                                       |\\n| ---------- | ------------------------------------------------ | ----------------------------------------------------------- |\\n| Porte      | un **contexte**                                  | une **compétence** reproductible                            |\\n| Exemple    | « tout sur le client X »                         | « comment rédiger un CR chez nous »                         |\\n| Contenu    | documents de référence, instructions, historique | un `SKILL.md` (mode d\'emploi) + des fichiers de support     |\\n| Chargement | quand on travaille dans le Project               | **automatiquement**, quand la Skill correspond à la demande |\\n| Partage    | au sein d\'une Team Anthropic                     | au sein d\'une Team Anthropic, comme un Project              |\\n\\nLes deux se combinent.\\n\\n## Structure minimale d\'une Skill\\n\\n- un **nom** + une **description** (quand l\'activer) ;\\n- un `SKILL.md` (étapes, règles, pièges) ;\\n- en option des templates / checklists.\\n\\nPour la créer : demandez à Claude « je veux créer une nouvelle skill », ou passez par le menu **Customize**.\\n\\n```text\\nJe veux créer une nouvelle skill.\\n```\\n"}}'),o={name:"handout-03-lab-2-tache-recurrente.md"};function i(s,e,u,l,d,c){return n(),r("div",null,[...e[0]||(e[0]=[a("",13)])])}const h=t(o,[["render",i]]);export{p as __pageData,h as default};
